namespace fs=std::filesystem;
struct Frame { std::vector<uint8_t> bytes; AnalysisLumaSource source; ActivePictureFrameIdentity identity; uint64_t policy=0,continuity=0,duration=0; int top=0,bottom=0,script=0,nearBar=0,optimization=0; bool discontinuity=false,repeat=false; };
Frame Read(const fs::path& path) {
 Frame f;auto txt=path;txt.replace_extension(L".txt");std::ifstream m(txt);std::string line,ver;std::getline(m,line);std::istringstream h(line);int format=0,encoding=0,color=0,range=0,disc=0,repeat=0,alignment=0;
 h>>f.source.width>>f.source.height>>f.source.rowBytes>>f.source.chromaRowBytes>>format>>encoding>>color>>f.top>>f.bottom>>f.script;
 if(!h)throw std::runtime_error("Malformed header");if(h>>range){if(range<0||range>2)throw std::runtime_error("Invalid range");f.source.range=static_cast<AnalysisLumaRange>(range);}
 m>>ver>>f.identity.transportGeneration>>f.identity.acceptedSequence>>f.identity.sourceFrameNumber>>f.identity.captureTimestamp>>f.identity.sourceFormatGeneration>>f.identity.viewportGeneration>>f.identity.rendererGeneration>>f.identity.analysisDomainKey>>f.policy>>f.continuity>>f.nearBar>>f.optimization>>f.duration>>disc>>repeat>>alignment;
 if(!m||ver!="identity_v1")throw std::runtime_error("Missing identity_v1");
 if(f.source.width<=0||f.source.width>8192||f.source.height<=0||f.source.height>4320||format<int(AnalysisLumaFormat::P010)||format>int(AnalysisLumaFormat::SdrTunnelRgb)||encoding<int(VideoFrameEncoding::UNKNOWN)||encoding>int(VideoFrameEncoding::DNxHR)||color<int(ColorSpace::UNKNOWN)||color>int(ColorSpace::BT_2020)||f.script<int(SubtitleScriptHint::GeneralMixed)||f.script>int(SubtitleScriptHint::Thai)||alignment<0||alignment>2||disc<0||disc>1||repeat<0||repeat>1)throw std::runtime_error("Metadata enum/size out of range");
 f.source.format=static_cast<AnalysisLumaFormat>(format);f.source.encoding=static_cast<VideoFrameEncoding>(encoding);f.source.colorspace=static_cast<ColorSpace>(color);f.source.rgbBitAlignment=uint8_t(alignment);f.source.generation=f.identity.transportGeneration;f.discontinuity=disc!=0;f.repeat=repeat!=0;
 std::ifstream p(path,std::ios::binary|std::ios::ate);auto size=p.tellg();if(!p||size<=0||size>std::streamoff(128ull*1024*1024))throw std::runtime_error("Invalid pixel file");f.bytes.resize(size_t(size));p.seekg(0);p.read(reinterpret_cast<char*>(f.bytes.data()),size);if(!p)throw std::runtime_error("Short pixel read");f.source.data=f.bytes.data();f.source.dataBytes=f.bytes.size();if(!f.source.IsValid())throw std::runtime_error("Invalid source");return f;
}
std::string Q(const std::string& s){std::string r="\"";for(char c:s){if(c=='\"')r+='\"';r+=c;}return r+'\"';}
const char* Class(ActivePictureClassification c){switch(c){case ActivePictureClassification::BAR_CROP_TRUSTED:return "BAR_CROP_TRUSTED";case ActivePictureClassification::FULL_RASTER_TRUSTED:return "FULL_RASTER_TRUSTED";case ActivePictureClassification::PROVISIONAL:return "PROVISIONAL";default:return "UNAVAILABLE";}}
void Bounds(std::ostream& o,const ActivePictureBounds& b){o<<b.left<<','<<b.top<<','<<b.right<<','<<b.bottom<<','<<b.aspectRatio<<','<<int(b.trustedBarAxes);}
void Edge(std::ostream& o,int index,uint64_t seq,const char* name,const ActivePictureEdgeEvidence& e){o<<index<<','<<seq<<','<<name<<','<<(e.barPixels>0)<<','<<e.barPixels<<','<<e.trusted<<','<<e.blackFraction<<','<<e.lumaFloor<<','<<e.lumaP90<<','<<e.lumaDispersion<<','<<e.texture<<','<<e.neutralChromaFraction<<','<<e.innerBoundaryContrast<<','<<e.continuity<<','<<e.confidence<<','<<int(e.matteReference.state)<<','<<e.matteReference.y<<','<<e.matteReference.u<<','<<e.matteReference.v;for(auto x:e.distributedSupportDepthRowsByQuartile)o<<','<<int(x);o<<'\n';}
int wmain(int argc,wchar_t** argv){try{
 if(argc!=3)throw std::runtime_error("Usage: native-ad-replay CAPTURE OUTPUT");fs::path capture=argv[1],out=argv[2];std::vector<fs::path> paths;for(const auto& e:fs::directory_iterator(capture))if(e.path().extension()==L".bin")paths.push_back(e.path());std::sort(paths.begin(),paths.end());
 std::ofstream result(out/L"detector.csv"),edges(out/L"edges.csv"),identity(out/L"identities.csv"),profiles(out/L"strict-profiles.csv");result<<std::setprecision(12);edges<<std::setprecision(12);profiles<<std::setprecision(12);
 result<<"frame,sequence,sequence_gap,discontinuity,repeat,source_format,range,available,class,proposed_left,proposed_top,proposed_right,proposed_bottom,proposed_ar,proposed_axes,trusted_left,trusted_top,trusted_right,trusted_bottom,trusted_ar,trusted_axes,h_state,h_reason,h_complete,h_candidate,v_state,v_reason,v_complete,v_candidate,reference,observed_floor,observed_cutoff,effective_floor,effective_cutoff,qualified_edges,unresolved_edges,qualified_axes,nominal_axes,nominal_reclassified,global_p90,global_cutoff,global_dark,distributed_dark,ar_dark,luma_samples,chroma_samples,recorded_top,recorded_bottom,retention_evaluated,retention_valid,retention_safe,retention_can_retain,relative_evaluated,relative_valid,relative_samples,relative_reason,reason\n";
 edges<<"frame,sequence,edge,measured,bar_pixels,trusted,black_fraction,floor,p90,dispersion,texture,neutral_fraction,inner_contrast,continuity,confidence,matte_state,matte_y,matte_u,matte_v,support_q0,support_q1,support_q2,support_q3\n";
 identity<<"frame,file,transport,sequence,source_frame,timestamp,source_format_generation,viewport,renderer,domain,policy,continuity,duration_100ns,discontinuity,cadence_repeat,script,near_bar,optimization,bytes,width,height,rowbytes,chromarowbytes,format,encoding,colorspace,range,alignment\n";
 profiles<<"frame,sequence,which,evaluated,completed,clean,top,bottom,samples,reference_y,reference_u,reference_v,max_dy,max_duv,mismatches,boundary_mismatches,deep_mismatches,first_x,first_y,reason\n";
 uint64_t previous=0;int i=0;for(const auto& p:paths){++i;auto f=Read(p);f.source.data=f.bytes.data();const auto raw=ExtractActivePictureEvidence(f.source);const auto global=EvaluateActivePictureGlobalNearBlack(f.source);const auto dark=EvaluateActivePictureArDarkness(f.source,raw,global);ActivePictureBounds base{0,f.top,f.source.width,f.bottom,f.source.width,f.source.height,double(f.source.width)/std::max(1,f.bottom-f.top),(f.top>0&&f.bottom<f.source.height)?ActivePictureBounds::BarAxes::TOP_BOTTOM:ActivePictureBounds::BarAxes::NONE};const auto retention=EvaluateActivePicturePresentationRetention(f.source,base,raw,global,dark);const auto relative=InspectRelativeBarContrast(f.source,raw,base);const auto& b=raw.blackReference;
 result<<i<<','<<f.identity.acceptedSequence<<','<<(previous&&f.identity.acceptedSequence>previous?f.identity.acceptedSequence-previous-1:0)<<','<<f.discontinuity<<','<<f.repeat<<','<<AnalysisLumaFormatName(f.source)<<','<<int(f.source.range)<<','<<raw.available<<','<<Class(raw.classification)<<',';Bounds(result,raw.proposedBounds);result<<',';Bounds(result,raw.trustedBounds);result<<','<<ActivePictureAxisStateName(raw.axisEvidence.horizontal.state)<<','<<ActivePictureAxisReasonName(raw.axisEvidence.horizontal.reason)<<','<<raw.axisEvidence.horizontal.scanComplete<<','<<raw.axisEvidence.horizontal.barCandidate<<','<<ActivePictureAxisStateName(raw.axisEvidence.vertical.state)<<','<<ActivePictureAxisReasonName(raw.axisEvidence.vertical.reason)<<','<<raw.axisEvidence.vertical.scanComplete<<','<<raw.axisEvidence.vertical.barCandidate<<','<<ActivePictureBlackReferenceModeName(b.mode)<<','<<b.observedFloor<<','<<b.observedThreshold<<','<<b.floor<<','<<b.threshold<<','<<int(b.qualifiedEdgeMask)<<','<<int(b.unresolvedEdgeMask)<<','<<int(b.qualifiedAxes)<<','<<int(b.nominalFullExtentAxes)<<','<<b.nominalReclassified<<','<<global.lumaP90<<','<<global.lumaCutoff<<','<<global.nearBlack<<','<<dark.distributedDarkPicture<<','<<dark.EffectiveNearBlack()<<','<<raw.lumaSamples<<','<<raw.chromaSamples<<','<<f.top<<','<<f.bottom<<','<<retention.analysisValid<<','<<retention.presentationValid<<','<<retention.currentlyPixelSafe<<','<<retention.CanRetainPresentation()<<','<<relative.evaluated<<','<<relative.valid<<','<<relative.samples<<','<<Q(relative.reason)<<','<<Q(raw.reason)<<'\n';
 for(auto e:{std::make_pair("left",&raw.left),std::make_pair("top",&raw.top),std::make_pair("right",&raw.right),std::make_pair("bottom",&raw.bottom)})Edge(edges,i,f.identity.acceptedSequence,e.first,*e.second);
 for(auto e:{std::make_pair("raw",&raw.verticalBarProfile),std::make_pair("guard",&raw.verticalBarGuardProfile)}){const auto& v=*e.second;profiles<<i<<','<<f.identity.acceptedSequence<<','<<e.first<<','<<v.evaluated<<','<<v.completed<<','<<v.clean<<','<<v.apertureTop<<','<<v.apertureBottom<<','<<v.samples<<','<<v.referenceY<<','<<v.referenceU<<','<<v.referenceV<<','<<v.maxLumaDelta<<','<<v.maxChromaDelta<<','<<v.mismatchSamples<<','<<v.boundaryMismatchSamples<<','<<v.deepMismatchSamples<<','<<v.firstMismatchX<<','<<v.firstMismatchY<<','<<Q(v.reason)<<'\n';}
 const auto& id=f.identity;identity<<i<<','<<p.filename().string()<<','<<id.transportGeneration<<','<<id.acceptedSequence<<','<<id.sourceFrameNumber<<','<<id.captureTimestamp<<','<<id.sourceFormatGeneration<<','<<id.viewportGeneration<<','<<id.rendererGeneration<<','<<id.analysisDomainKey<<','<<f.policy<<','<<f.continuity<<','<<f.duration<<','<<f.discontinuity<<','<<f.repeat<<','<<f.script<<','<<f.nearBar<<','<<f.optimization<<','<<f.bytes.size()<<','<<f.source.width<<','<<f.source.height<<','<<f.source.rowBytes<<','<<f.source.chromaRowBytes<<','<<int(f.source.format)<<','<<int(f.source.encoding)<<','<<int(f.source.colorspace)<<','<<int(f.source.range)<<','<<int(f.source.rgbBitAlignment)<<'\n';previous=id.acceptedSequence;if(i==1||i==(int(paths.size())+1)/2||i==int(paths.size()))std::cout<<i<<" seq="<<id.acceptedSequence<<" class="<<Class(raw.classification)<<" proposed="<<raw.proposedBounds.left<<','<<raw.proposedBounds.top<<'-'<<raw.proposedBounds.right<<','<<raw.proposedBounds.bottom<<" trusted="<<raw.trustedBounds.left<<','<<raw.trustedBounds.top<<'-'<<raw.trustedBounds.right<<','<<raw.trustedBounds.bottom<<" floor="<<b.floor<<" cutoff="<<b.threshold<<" reason="<<raw.reason<<'\n';}
 std::cout<<"Frames measured="<<paths.size()<<"; no transition model or history synthesized\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
